class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

    def is_square(self):
        return self.width == self.height

w, h = [float(x) for x in input().split()]
rect = Rectangle(w, h)
print(f"Area: {rect.area():.2f}")
print(f"Perimeter: {rect.perimeter():.2f}")
