class Student:
    PASS_MARK = 50.0

    def __init__(self, name, marks):
        self.name = name
        self.marks = marks

    def average(self):
        return sum(self.marks) / len(self.marks)

    def status(self):
        return "PASS" if self.average() >= self.PASS_MARK else "FAIL"

