print(f"{st.name}: Average {st.average():.2f} ({st.status()})")

class Circle:
    PI = 3.14159

    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return self.PI * (self.radius ** 2)

    def circumference(self):
        return 2 * self.PI * self.radius

    def scale(self, factor):
        self.radius *= factor

r, factor = [float(x) for x in input().split()]
c = Circle(r)
print(f"Before: Area={c.area():.2f} Circ={c.circumference():.2f}")
c.scale(factor)
print(f"After: Area={c.area():.2f} Circ={c.circumference():.2f}")

class Counter:
    total_counters = 0

    def __init__(self, start=0):
        self.value = start
        Counter.total_counters += 1

    def inc(self, step=1):
        self.value += step

    def dec(self, step=1):
        self.value -= step

