class Temperature:
    def __init__(self, celsius):
        self.celsius = float(celsius)

    @staticmethod
    def c_to_f(c):
        return (c * 9.0 / 5.0) + 32.0

    @staticmethod
    def f_to_c(f):
        return (f - 32.0) * 5.0 / 9.0

    @classmethod
    def from_fahrenheit(cls, f):
        return cls(cls.f_to_c(float(f)))

    def is_freezing(self):
        return self.celsius <= 0.0

unit, val_s = input().split()
val = float(val_s)
temp = Temperature(val) if unit == "C" else Temperature.from_fahrenheit(val)
freeze = "YES" if temp.is_freezing() else "NO"
print(f"C: {temp.celsius:.2f} | F: {Temperature.c_to_f(temp.celsius):.2f} | Freezing: {freeze}")

class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

    @property
    def price(self):
        return self._price

    @price.setter
    def price(self, value):
        val = float(value)
        if val <= 0:
            raise ValueError("Price must be positive")
        self._price = val

    def apply_discount(self, percent):
        pct = float(percent)
        if pct < 0 or pct >= 100:
            raise ValueError("Invalid discount")
        self.price = self._price * (1.0 - pct / 100.0)

