pl = Playlist(pl_name)
q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "ADD":
        pl.add_song(Song(parts[1], int(parts[2])))
    elif parts[0] == "REMOVE":
        pl.remove_song(parts[1])
print(f"{pl.name}: {pl.count()} songs, {pl.total_duration()}")

