class Shape:
    def area(self):
        raise NotImplementedError

class Rect(Shape):
    def __init__(self, w, h):
        self.w = float(w)
        self.h = float(h)

    def area(self):
        return self.w * self.h

class Tri(Shape):
    def __init__(self, b, h):
        self.b = float(b)
        self.h = float(h)

    def area(self):
        return 0.5 * self.b * self.h

class Circ(Shape):
    PI = 3.14159

    def __init__(self, r):
        self.r = float(r)

    def area(self):
        return self.PI * (self.r ** 2)

