class Notifier:
    def send(self, recipient, msg):
        raise NotImplementedError

class EmailNotifier(Notifier):
    def send(self, recipient, msg):
        return f"[EMAIL -> {recipient}] {msg}"

class SMSNotifier(Notifier):
    def send(self, recipient, msg):
        text = msg[:12] + "..." if len(msg) > 15 else msg
        return f"[SMS -> {recipient}] {text}"

class PushNotifier(Notifier):
    def send(self, recipient, msg):
        return f"[PUSH -> {recipient}] {msg}"

def dispatch(notifier, recipient, msg):
    return notifier.send(recipient, msg)

channels = {
    "EMAIL": EmailNotifier(),
    "SMS": SMSNotifier(),
    "PUSH": PushNotifier(),
}

n = int(input())
for _ in range(n):
    ch, rec, msg = input().split("|", 2)
    print(dispatch(channels[ch.strip()], rec.strip(), msg))

import math

class Vector2D:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __eq__(self, other):
        if not isinstance(other, Vector2D):
            return NotImplemented
        return self.x == other.x and self.y == other.y

    def magnitude(self):
        return math.hypot(self.x, self.y)

    def __str__(self):
        return f"({self.x}, {self.y})"

