class LibraryBook:
    def __init__(self, isbn, copies):
        self.isbn = isbn
        self.copies = int(copies)

class Member:
    def __init__(self, member_id, max_books=2):
        self.member_id = member_id
        self.max_books = max_books
        self.borrowed = set()

class Library:
    def __init__(self):
        self.books = {}
        self.members = {}

    def add_book(self, isbn, copies):
        self.books[isbn] = LibraryBook(isbn, copies)

    def add_member(self, member_id):
        self.members[member_id] = Member(member_id)

    def borrow_book(self, member_id, isbn):
        book = self.books.get(isbn)
        member = self.members.get(member_id)
        if not book or not member:
            return False
        if book.copies <= 0 or isbn in member.borrowed or len(member.borrowed) >= member.max_books:
            return False
        book.copies -= 1
        member.borrowed.add(isbn)
        return True

    def return_book(self, member_id, isbn):
        book = self.books.get(isbn)
        member = self.members.get(member_id)
        if not book or not member or isbn not in member.borrowed:
            return False
        member.borrowed.remove(isbn)
        book.copies += 1
        return True

