from abc import ABC, abstractmethod

class PaymentProcessor(ABC):
    @abstractmethod
    def fee(self, amount):
        pass

    def process(self, amount):
        f = self.fee(amount)
        return amount, f, amount + f

class CardProcessor(PaymentProcessor):
    def fee(self, amount):
        return amount * 0.025 + 0.30

class WalletProcessor(PaymentProcessor):
    def fee(self, amount):
        return min(amount * 0.01, 5.00)

processors = {"CARD": CardProcessor(), "WALLET": WalletProcessor()}
n = int(input())
total_fees = 0.0
for _ in range(n):
    kind, amt_s = input().split()
    base, f, tot = processors[kind].process(float(amt_s))
    total_fees += f
    print(f"{kind} Base={base:.2f} Fee={f:.2f} Total={tot:.2f}")
print(f"Total Fees: {total_fees:.2f}")

class PermissionMixin:
    def __init__(self, roles=None, **kwargs):
        super().__init__(**kwargs)
        self.roles = set(roles or [])

    def has_role(self, role):
        return role in self.roles

class AuditMixin:
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.logs = []

    def record(self, entry):
        self.logs.append(entry)

class UserAccount(PermissionMixin, AuditMixin):
    def __init__(self, username, roles):
        super().__init__(roles=roles)
        self.username = username

    def perform(self, required_role, action):
        if self.has_role(required_role):
            self.record(f"{self.username}: ALLOW:{action}")
            return True
        self.record(f"{self.username}: DENY:{action}")
        return False

