class CartItem:
    def __init__(self, sku, price, qty):
        self.sku = sku
        self.price = float(price)
        self.qty = int(qty)

class Coupon:
    def __init__(self, kind, value):
        self.kind = kind
        self.value = float(value)

    def compute_discount(self, subtotal):
        if self.kind == "PCT":
            return subtotal * (self.value / 100.0)
        return min(subtotal, self.value)

class ShoppingCart:
    def __init__(self, tax_rate=0.05):
        self.items = {}
        self.coupon = None
        self.tax_rate = tax_rate

    def add(self, sku, price, qty):
        if sku in self.items:
            self.items[sku].qty += int(qty)
        else:
            self.items[sku] = CartItem(sku, price, qty)

    def remove(self, sku, qty):
        if sku not in self.items:
            return
        self.items[sku].qty -= int(qty)
        if self.items[sku].qty <= 0:
            del self.items[sku]

    def apply_coupon(self, coupon):
        self.coupon = coupon

    def checkout(self):
        subtotal = sum(it.price * it.qty for it in self.items.values())
        discount = self.coupon.compute_discount(subtotal) if self.coupon else 0.0
        taxable = subtotal - discount
        tax = taxable * self.tax_rate
        return subtotal, discount, tax, taxable + tax

