class Task:
    NEXT_STATE = {"TODO": "IN_PROGRESS", "IN_PROGRESS": "DONE"}

    def __init__(self, task_id, priority, assignee, seq):
        self.task_id = task_id
        self.priority = int(priority)
        self.assignee = assignee
        self.seq = seq
        self.status = "TODO"

    def advance(self):
        if self.status not in self.NEXT_STATE:
            return False
        self.status = self.NEXT_STATE[self.status]
        return True

class TaskScheduler:
    def __init__(self):
        self.tasks = {}
        self._seq = 0

    def add_task(self, task_id, priority, assignee):
        self._seq += 1
        self.tasks[task_id] = Task(task_id, priority, assignee, self._seq)

    def advance(self, task_id):
        t = self.tasks.get(task_id)
        return t.advance() if t else False

    def next_task(self, assignee):
        candidates = [
            t for t in self.tasks.values()
            if t.assignee == assignee and t.status != "DONE"
        ]
        if not candidates:
            return None
        return min(candidates, key=lambda t: (t.priority, t.seq))

    def pending_count(self):
        return sum(1 for t in self.tasks.values() if t.status != "DONE")

sched = TaskScheduler()
q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "ADD":
        sched.add_task(parts[1], int(parts[2]), parts[3])
    elif parts[0] == "ADVANCE":
        print("OK" if sched.advance(parts[1]) else "FAIL")
    elif parts[0] == "NEXT":
        t = sched.next_task(parts[1])
        print(f"{t.task_id}:{t.status}" if t else "NONE")
print(f"Pending: {sched.pending_count()}")

class Account:
    def __init__(self, acc_id, balance):
        self.acc_id = acc_id
        self.balance = float(balance)

    def deposit(self, amt):
        if amt <= 0:
            return False
        self.balance += amt
        return True

    def withdraw(self, amt):
        if amt <= 0 or amt > self.balance:
            return False
        self.balance -= amt
        return True

    def end_of_month(self):
        pass

class SavingsAccount(Account):
    def __init__(self, acc_id, balance, rate=0.05):
        super().__init__(acc_id, balance)
        self.rate = rate

    def end_of_month(self):
        self.balance *= (1.0 + self.rate)

class CheckingAccount(Account):
    def __init__(self, acc_id, balance, overdraft=100.0):
        super().__init__(acc_id, balance)
        self.overdraft = overdraft

    def withdraw(self, amt):
        if amt <= 0 or (self.balance - amt) < -self.overdraft:
            return False
        self.balance -= amt
        return True

class Bank:
    def __init__(self):
        self.accounts = {}

    def create(self, kind, acc_id, balance):
        if kind == "SAVINGS":
            self.accounts[acc_id] = SavingsAccount(acc_id, balance)
        else:
            self.accounts[acc_id] = CheckingAccount(acc_id, balance)

    def deposit(self, acc_id, amt):
        acc = self.accounts.get(acc_id)
        return acc.deposit(amt) if acc else False

    def withdraw(self, acc_id, amt):
        acc = self.accounts.get(acc_id)
        return acc.withdraw(amt) if acc else False

    def transfer(self, src_id, dst_id, amt):
        src = self.accounts.get(src_id)
        dst = self.accounts.get(dst_id)
        if not src or not dst or src_id == dst_id or amt <= 0:
            return False
        if not src.withdraw(amt):
            return False
        dst.deposit(amt)
        return True

    def apply_interest(self):
        for acc in self.accounts.values():
            acc.end_of_month()

bank = Bank()
q = int(input())
for _ in range(q):
